/* ═══════════════════════════ TOKENS ═══════════════════════════ */
:root {
    --bg: #08090b;
    --bg-1: #0b0c10;
    --bg-2: #0d0f13;
    --bg-3: #111319;
    --border: rgba(255, 255, 255, .08);
    --border-2: rgba(255, 255, 255, .13);
    --border-violet: rgba(155, 125, 255, .28);

    --violet: #7c5cff;
    --violet-bright: #9b7dff;
    --violet-dim: #5b3fd1;
    --pink: #ff5da2;
    --amber: #ffb454;

    --grad: linear-gradient(120deg, #9b7dff 0%, #c084fc 45%, #ff5da2 100%);
    --grad-soft: linear-gradient(120deg, rgba(155, 125, 255, .16) 0%, rgba(255, 93, 162, .10) 100%);
    --grad-btn: linear-gradient(135deg, #8a63ff 0%, #b45cff 60%, #ff5da2 100%);

    --tx: #f5f5f7;
    --tx-2: #b7b7c2;
    --tx-3: #82828e;
    --tx-4: #4c4c56;

    --success: #4ade80;
    --danger: #f87171;
    --warning: #fb923c;

    --r-2xl: 28px;
    --r-xl: 22px;
    --r-lg: 16px;
    --r-md: 12px;
    --r-sm: 8px;
    --r-pill: 999px;

    --ease: all .22s cubic-bezier(.4, 0, .2, 1);
    --ease-spring: all .5s cubic-bezier(.16, 1, .3, 1);

    --nav-h: 72px;
    --font-display: 'Clash Display', 'Plus Jakarta Sans', sans-serif;
    --font-body: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', ui-monospace, monospace;

    --shadow-card: 0 1px 0 rgba(255, 255, 255, .03) inset, 0 10px 30px -12px rgba(0, 0, 0, .6);
    --shadow-glow: 0 0 0 1px rgba(124, 92, 255, .22), 0 12px 40px -8px rgba(124, 92, 255, .28);

    --ink: #04010f;
    --plum: #9b45ff;
    --plum-bright: #bf76ff;
    --rose: #e8399a;
    --amber-orange: #ff6d2e;
    --grad-nav: linear-gradient(135deg, #bf76ff 0%, #e8399a 52%, #ff6d2e 100%);
    --grad-btn-nav: linear-gradient(135deg, #9b45ff 0%, #e8399a 100%);
    --nav-border: rgba(155, 69, 255, .16);
    --glass-bg: rgba(15, 6, 35, .45);
    --glass-border: rgba(191, 118, 255, .18);
    --glass-blur: saturate(180%) blur(24px);
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: .001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: .001ms !important;
        scroll-behavior: auto !important;
    }
}

/* ═══════════════════════════ RESET ═══════════════════════════ */
*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}
html {
    font-size: 16px;
    scroll-behavior: smooth;
    height: 100%;
}
body {
    font-family: var(--font-body);
    background: var(--bg);
    color: var(--tx);
    min-height: 100vh;
    padding-top: calc(var(--nav-h) + 20px);
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
    font-size: 16px;
    line-height: 1.5;
}
img {
    max-width: 100%;
    display: block;
}
button,
input,
select,
textarea {
    font-family: inherit;
    color: inherit;
}
a {
    color: inherit;
    text-decoration: none;
}
::selection {
    background: rgba(155, 125, 255, .35);
    color: #fff;
}
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}
::-webkit-scrollbar-track {
    background: transparent;
}
::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, .12);
    border-radius: 4px;
}
:focus-visible {
    outline: 2px solid var(--violet-bright);
    outline-offset: 2px;
    border-radius: 4px;
}

/* ═══════════════════════════ BACKGROUND ═══════════════════════════ */
.bg-canvas {
    position: fixed;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    overflow: hidden;
}
.bg-orb {
    position: absolute;
    border-radius: 50%;
    filter: blur(100px);
    opacity: .55;
    animation: orbFloat 26s ease-in-out infinite;
}
.bg-orb-1 {
    width: 620px;
    height: 620px;
    top: -220px;
    left: -160px;
    background: radial-gradient(circle, rgba(124, 92, 255, .16) 0%, transparent 70%);
}
.bg-orb-2 {
    width: 520px;
    height: 520px;
    top: 30%;
    right: -200px;
    background: radial-gradient(circle, rgba(255, 93, 162, .10) 0%, transparent 70%);
    animation-delay: -10s;
}
.bg-grid {
    position: absolute;
    inset: 0;
    background-image: linear-gradient(rgba(255, 255, 255, .025) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, .025) 1px, transparent 1px);
    background-size: 64px 64px;
    mask-image: radial-gradient(ellipse 80% 50% at 50% 0%, #000 40%, transparent 100%);
}
@keyframes orbFloat {
    0%,
    100% {
        transform: translate(0, 0) scale(1);
    }
    50% {
        transform: translate(24px, 30px) scale(1.05);
    }
}

/* ═══════════════════════════ SKIP LINK ═══════════════════════════ */
.skip-link {
    position: absolute;
    top: -9999px;
    left: 50%;
    transform: translateX(-50%);
    padding: 12px 22px;
    background: var(--violet);
    color: #fff;
    border-radius: var(--r-md);
    font-weight: 700;
    z-index: 9999;
}
.skip-link:focus {
    top: 12px;
}

/* ═══════════════════════════ DYNAMIC ISLAND NAV ═══════════════════════════ */
.dynamic-island {
    position: fixed;
    top: 12px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 1000;
    width: auto;
    min-width: 280px;
    max-width: 92vw;
    height: 56px;
    background: rgba(8, 3, 22, .82);
    backdrop-filter: saturate(180%) blur(24px);
    -webkit-backdrop-filter: saturate(180%) blur(24px);
    border-radius: var(--r-pill);
    border: 1px solid rgba(191, 118, 255, .12);
    box-shadow: 0 8px 32px rgba(0, 0, 0, .5);
    display: flex;
    align-items: center;
    padding: 0 6px;
    gap: 2px;
    user-select: none;
    transition: all .3s cubic-bezier(.34, 1.56, .64, 1);
}
.dynamic-island::before {
    content: '';
    position: absolute;
    inset: -1px;
    border-radius: var(--r-pill);
    padding: 1px;
    background: linear-gradient(135deg, rgba(191, 118, 255, .12), rgba(232, 57, 154, .06));
    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    pointer-events: none;
}
.island-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    height: 100%;
    padding: 0 4px;
    position: relative;
    z-index: 1;
}

.island-brand {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
    text-decoration: none;
    padding: 0 6px 0 4px;
    border-radius: var(--r-sm);
    transition: var(--ease);
}
.island-brand:hover {
    background: rgba(155, 69, 255, .04);
}
.island-brand-logo {
    width: 32px;
    height: 32px;
    border-radius: var(--r-xs);
    background: linear-gradient(135deg, rgba(155, 69, 255, .2), rgba(232, 57, 154, .12));
    border: 1px solid rgba(155, 69, 255, .2);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    overflow: hidden;
}
.island-brand-logo img {
    width: 18px;
    height: 18px;
    object-fit: contain;
}
.island-brand-text {
    font-family: 'Clash Display', sans-serif;
    font-size: .92rem;
    font-weight: 700;
    background: var(--grad-nav);
    background-size: 200% 200%;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    animation: gradShift 6s ease infinite;
    white-space: nowrap;
}


.island-links {
    display: flex;
    align-items: center;
    gap: 1px;
    flex: 1;
    justify-content: center;
    padding: 0 4px;
}
.island-link {
    display: flex;
    align-items: center;
    gap: 3px;
    padding: 5px 12px;
    border-radius: var(--r-sm);
    color: var(--tx-3);
    font-size: .75rem;
    font-weight: 600;
    background: none;
    border: none;
    cursor: pointer;
    transition: var(--ease);
    font-family: inherit;
    text-decoration: none;
    white-space: nowrap;
    position: relative;
}
.island-link:hover {
    color: var(--tx-2);
    background: rgba(155, 69, 255, .06);
}
.island-link .chevron {
    font-size: .5rem;
    opacity: .5;
    transition: transform .22s ease;
    margin-left: 1px;
}
.island-link .link-badge {
    font-size: .45rem;
    font-weight: 800;
    text-transform: uppercase;
    padding: 1px 5px;
    border-radius: var(--r-pill);
    background: rgba(232, 57, 154, .12);
    border: 1px solid rgba(232, 57, 154, .18);
    color: var(--rose);
    margin-left: 1px;
}

.island-dropdown-wrap {
    position: relative;
}
.island-dropdown {
    position: absolute;
    top: calc(100% + 8px);
    left: 50%;
    transform: translateX(-50%) translateY(4px);
    min-width: 200px;
    background: rgba(8, 3, 22, .96);
    backdrop-filter: saturate(180%) blur(24px);
    -webkit-backdrop-filter: saturate(180%) blur(24px);
    border: 1px solid rgba(155, 69, 255, .12);
    border-radius: var(--r-lg);
    padding: 6px 4px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, .7);
    opacity: 0;
    pointer-events: none;
    transition: opacity .2s ease, transform .2s ease;
    z-index: 100;
}
.island-dropdown-wrap:hover .island-dropdown,
.island-dropdown-wrap.open .island-dropdown {
    opacity: 1;
    pointer-events: all;
    transform: translateX(-50%) translateY(0);
}
.island-dropdown a,
.island-dropdown .dd-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 12px;
    border-radius: var(--r-sm);
    color: var(--tx-3);
    font-size: .73rem;
    font-weight: 500;
    text-decoration: none;
    transition: var(--ease);
    cursor: pointer;
    background: none;
    border: none;
    width: 100%;
    text-align: left;
    font-family: inherit;
}
.island-dropdown a:hover,
.island-dropdown .dd-item:hover {
    background: rgba(155, 69, 255, .06);
    color: var(--tx-2);
}
.island-dropdown .dd-icon {
    font-size: .9rem;
    flex-shrink: 0;
}
.island-dropdown .dd-label {
    flex: 1;
}
.island-dropdown .dd-badge {
    font-size: .45rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 1px 6px;
    border-radius: var(--r-pill);
    background: rgba(232, 57, 154, .10);
    border: 1px solid rgba(232, 57, 154, .16);
    color: var(--rose);
}
.island-dropdown .dd-divider {
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(155, 69, 255, .08), transparent);
    margin: 4px 8px;
}
.island-dropdown .dd-admin {
    display: none;
}
.island-dropdown .dd-admin.visible {
    display: flex;
}

.island-right {
    display: flex;
    align-items: center;
    gap: 4px;
    flex-shrink: 0;
    padding-right: 2px;
}
.island-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 4px;
    padding: 5px 14px;
    border-radius: var(--r-pill);
    border: none;
    cursor: pointer;
    font-family: inherit;
    font-size: .73rem;
    font-weight: 700;
    transition: var(--ease-spring);
    text-decoration: none;
    white-space: nowrap;
    position: relative;
    overflow: hidden;
}
.island-btn::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 50%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .08), transparent);
    transition: left .5s ease;
    pointer-events: none;
}
.island-btn:hover::before {
    left: 140%;
}
.island-btn-primary {
    background: var(--grad-btn-nav);
    color: #fff;
    box-shadow: 0 2px 12px rgba(155, 69, 255, .25);
}
.island-btn-primary:hover {
    box-shadow: 0 4px 20px rgba(155, 69, 255, .35);
    transform: translateY(-1px);
}
.island-btn-secondary {
    background: rgba(155, 69, 255, .06);
    color: var(--plum-bright);
    border: 1px solid rgba(155, 69, 255, .12);
}
.island-btn-secondary:hover {
    background: rgba(155, 69, 255, .12);
    border-color: rgba(155, 69, 255, .22);
    transform: translateY(-1px);
}
.island-btn-ghost {
    background: transparent;
    color: var(--tx-3);
    border: 1px solid rgba(255, 255, 255, .04);
}
.island-btn-ghost:hover {
    background: rgba(255, 255, 255, .04);
    color: var(--tx-2);
}
.island-btn-sm {
    padding: 4px 10px;
    font-size: .68rem;
}

.island-profile {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 2px 10px 2px 4px;
    border-radius: var(--r-pill);
    background: rgba(155, 69, 255, .04);
    border: 1px solid rgba(155, 69, 255, .08);
    cursor: pointer;
    transition: var(--ease);
}
.island-profile:hover {
    background: rgba(155, 69, 255, .08);
}
.island-avatar {
    width: 26px;
    height: 26px;
    border-radius: 50%;
    background: var(--grad-btn-nav);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: .65rem;
    font-weight: 800;
    color: #fff;
    flex-shrink: 0;
    box-shadow: 0 0 8px rgba(155, 69, 255, .15);
}
.island-profile-email {
    font-size: .68rem;
    font-weight: 600;
    color: var(--tx-2);
    max-width: 80px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}
.island-profile .chevron {
    font-size: .45rem;
    color: var(--tx-4);
}

.island-hamburger {
    display: none;
    flex-direction: column;
    gap: 3px;
    padding: 6px 8px;
    background: none;
    border: none;
    cursor: pointer;
    color: var(--tx);
    border-radius: var(--r-sm);
    transition: var(--ease);
    flex-shrink: 0;
}
.island-hamburger:hover {
    background: rgba(155, 69, 255, .04);
}
.island-hamburger span {
    display: block;
    width: 18px;
    height: 1.5px;
    background: currentColor;
    border-radius: 1px;
    transition: transform .28s cubic-bezier(.4, 0, .2, 1), opacity .2s ease;
}
.island-hamburger.open span:nth-child(1) {
    transform: translateY(4.5px) rotate(45deg);
}
.island-hamburger.open span:nth-child(2) {
    opacity: 0;
    transform: scaleX(0);
}
.island-hamburger.open span:nth-child(3) {
    transform: translateY(-4.5px) rotate(-45deg);
}

.island-mobile-overlay {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 999;
    background: rgba(4, 1, 15, .92);
    backdrop-filter: blur(32px) saturate(160%);
    -webkit-backdrop-filter: blur(32px) saturate(160%);
    padding: 80px 20px 32px;
    overflow-y: auto;
    flex-direction: column;
    gap: 2px;
    animation: overlayFade .3s ease both;
}
@keyframes overlayFade {
    from {
        opacity: 0;
        transform: scale(.97);
    }
    to {
        opacity: 1;
        transform: scale(1);
    }
}
.island-mobile-overlay.open {
    display: flex;
}
.island-mobile-overlay .mob-section {
    padding: 8px 0 2px 12px;
    font-size: .55rem;
    text-transform: uppercase;
    letter-spacing: .12em;
    color: var(--tx-4);
    font-weight: 800;
    margin-top: 4px;
}
.island-mobile-overlay .mob-link {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 14px;
    border-radius: var(--r-md);
    color: var(--tx-3);
    font-size: .85rem;
    font-weight: 600;
    text-decoration: none;
    transition: var(--ease);
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-family: inherit;
    cursor: pointer;
}
.island-mobile-overlay .mob-link:hover {
    background: rgba(155, 69, 255, .05);
    color: var(--tx-2);
}
.island-mobile-overlay .mob-link .mob-icon {
    font-size: 1rem;
    flex-shrink: 0;
}
.island-mobile-overlay .mob-link .mob-badge {
    font-size: .45rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 1px 6px;
    border-radius: var(--r-pill);
    background: rgba(232, 57, 154, .10);
    border: 1px solid rgba(232, 57, 154, .16);
    color: var(--rose);
    margin-left: auto;
}
.island-mobile-overlay .mob-divider {
    height: 1px;
    background: linear-gradient(90deg, transparent, rgba(155, 69, 255, .08), transparent);
    margin: 4px 12px;
}
.island-mobile-overlay .mob-auth-row {
    padding: 12px 14px 4px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}
.island-mobile-overlay .mob-auth-row .mob-email {
    font-size: .78rem;
    color: var(--tx-2);
    font-weight: 600;
    padding: 0 4px 4px;
}

.island-overlay-close {
    position: fixed;
    top: 16px;
    right: 20px;
    z-index: 1001;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: rgba(155, 69, 255, .06);
    border: 1px solid rgba(155, 69, 255, .12);
    color: var(--tx-3);
    font-size: 1.2rem;
    cursor: pointer;
    display: none;
    align-items: center;
    justify-content: center;
    transition: var(--ease);
}
.island-overlay-close:hover {
    background: rgba(155, 69, 255, .12);
    color: var(--tx);
}
.island-overlay-close.visible {
    display: flex;
}

@keyframes gradShift {
    0%,
    100% {
        background-position: 0% 50%;
    }
    50% {
        background-position: 100% 50%;
    }
}

/* ═══════ RESPONSIVE NAV ═══════ */
@media (max-width:1024px) {
    .dynamic-island {
        min-width: 200px;
        height: 50px;
        top: 10px;
    }
    .island-brand-text {
        font-size: .8rem;
    }

    .island-link {
        font-size: .7rem;
        padding: 4px 8px;
    }
    .island-btn {
        font-size: .68rem;
        padding: 4px 10px;
    }
    .island-profile-email {
        max-width: 60px;
        font-size: .62rem;
    }
}
@media (max-width:820px) {
    .island-links {
        display: none;
    }
    .island-hamburger {
        display: flex;
    }
    .dynamic-island {
        min-width: 140px;
        height: 44px;
        top: 8px;
        padding: 0 4px;
    }
    .island-brand-text {
        font-size: .72rem;
    }
    .island-brand-logo {
        width: 26px;
        height: 26px;
    }
    .island-brand-logo img {
        width: 15px;
        height: 15px;
    }
    .island-right .island-btn-secondary {
        display: none;
    }
    .island-right .island-btn-primary {
        padding: 3px 10px;
        font-size: .62rem;
    }
    .island-profile-email {
        max-width: 50px;
        font-size: .58rem;
    }
    .island-avatar {
        width: 22px;
        height: 22px;
        font-size: .55rem;
    }
    .island-profile {
        padding: 1px 6px 1px 2px;
    }
    .island-overlay-close.visible {
        display: flex;
    }
    body {
        padding-top: 64px;
    }
}
@media (max-width:480px) {
    .dynamic-island {
        min-width: 100px;
        height: 40px;
        top: 6px;
        padding: 0 2px;
    }
    .island-brand-text {
        font-size: .65rem;
    }
    .island-brand-logo {
        width: 22px;
        height: 22px;
    }
    .island-brand-logo img {
        width: 13px;
        height: 13px;
    }
    .island-brand {
        gap: 4px;
        padding: 0 2px;
    }
    .island-right .island-btn-primary {
        padding: 2px 8px;
        font-size: .55rem;
    }
    .island-right .island-btn-ghost {
        display: none;
    }
    .island-hamburger span {
        width: 15px;
        height: 1.5px;
    }
    .island-hamburger {
        padding: 4px 6px;
        gap: 2.5px;
    }
    .island-profile-email {
        max-width: 36px;
        font-size: .52rem;
    }
    .island-avatar {
        width: 20px;
        height: 20px;
        font-size: .5rem;
    }
    body {
        padding-top: 56px;
    }
}

/* ═══════════════════════════ UTILITY ═══════════════════════════ */
.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 8px 18px;
    border-radius: var(--r-md);
    border: none;
    cursor: pointer;
    font-family: inherit;
    font-size: .8rem;
    font-weight: 700;
    transition: var(--ease-spring);
    text-decoration: none;
    white-space: nowrap;
    position: relative;
    overflow: hidden;
}
.btn::before {
    content: '';
    position: absolute;
    top: 0;
    left: -100%;
    width: 60%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .1), transparent);
    transition: left .5s ease;
    pointer-events: none;
}
.btn:hover::before {
    left: 140%;
}
.btn-primary {
    background: var(--grad-btn);
    color: #fff;
    box-shadow: 0 4px 20px rgba(155, 69, 255, .35);
}
.btn-primary:hover {
    box-shadow: 0 8px 32px rgba(155, 69, 255, .5);
    transform: translateY(-1px);
}
.btn-secondary {
    background: rgba(155, 69, 255, .08);
    color: var(--violet-bright);
    border: 1px solid rgba(155, 69, 255, .18);
}
.btn-secondary:hover {
    background: rgba(155, 69, 255, .16);
    border-color: rgba(155, 69, 255, .35);
    transform: translateY(-1px);
}
.btn-ghost {
    background: transparent;
    color: var(--tx-3);
    border: 1px solid rgba(255, 255, 255, .06);
}
.btn-ghost:hover {
    background: rgba(255, 255, 255, .04);
    color: var(--tx-2);
    border-color: rgba(255, 255, 255, .12);
}
.btn-sm {
    padding: 6px 14px;
    font-size: .74rem;
}
.btn-full {
    width: 100%;
}

.main-wrap {
    max-width: 1240px;
    margin: 0 auto;
    padding: 0 28px 60px;
    position: relative;
    z-index: 1;
}

.section {
    padding: 64px 0;
}
.section-divider {
    height: 1px;
    background: linear-gradient(90deg, transparent, var(--border) 20%, var(--border) 80%, transparent);
    margin: 0;
}
.section-eyebrow {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: .74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .09em;
    color: var(--violet-bright);
    margin-bottom: 16px;
}
.section-title {
    font-family: var(--font-display);
    font-size: clamp(1.9rem, 3.4vw, 2.7rem);
    font-weight: 600;
    letter-spacing: -.02em;
    line-height: 1.14;
    color: var(--tx);
    margin-bottom: 14px;
}
.section-sub {
    font-size: 1.02rem;
    color: var(--tx-3);
    max-width: 560px;
    line-height: 1.65;
}
.grad {
    background: var(--grad);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

.reveal {
    opacity: 0;
    transform: translateY(18px);
    transition: opacity .7s cubic-bezier(.16, 1, .3, 1), transform .7s cubic-bezier(.16, 1, .3, 1);
}
.reveal.in {
    opacity: 1;
    transform: translateY(0);
}
.stagger-1.in {
    transition-delay: .05s;
}
.stagger-2.in {
    transition-delay: .13s;
}
.stagger-3.in {
    transition-delay: .21s;
}

.back-link {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--tx-3);
    font-weight: 600;
    font-size: .85rem;
    transition: var(--ease);
    margin-bottom: 8px;
}
.back-link:hover {
    color: var(--violet-bright);
    transform: translateX(-4px);
}

/* ═══════════════════════════ DISCLAIMER CONTENT ═══════════════════════════ */
.disclaimer-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-top: 8px;
}
.disclaimer-card {
    background: var(--bg-1);
    border: 1px solid var(--border);
    border-radius: var(--r-xl);
    padding: 24px 26px;
    transition: var(--ease);
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.disclaimer-card:hover {
    border-color: var(--border-violet);
    transform: translateY(-2px);
    box-shadow: var(--shadow-card);
}
.disclaimer-card .dc-icon {
    font-size: 1.4rem;
    margin-bottom: 4px;
}
.disclaimer-card .dc-title {
    font-family: var(--font-display);
    font-size: 1.05rem;
    font-weight: 600;
    color: var(--tx);
    letter-spacing: -.01em;
    margin-bottom: 2px;
}
.disclaimer-card .dc-body {
    font-size: .85rem;
    color: var(--tx-3);
    line-height: 1.65;
}
.disclaimer-card .dc-body ul {
    padding-left: 18px;
    margin: 4px 0 0;
}
.disclaimer-card .dc-body ul li {
    font-size: .82rem;
    color: var(--tx-3);
    line-height: 1.6;
    margin-bottom: 2px;
}
.disclaimer-card .dc-body ul li strong {
    color: var(--tx-2);
}

.email-pill {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: rgba(155, 69, 255, .08);
    padding: 6px 18px 6px 14px;
    border-radius: var(--r-pill);
    border: 1px solid rgba(155, 69, 255, .2);
    color: var(--violet-bright);
    font-weight: 600;
    font-size: .9rem;
}

.footer-meta-note {
    margin-top: 16px;
    padding: 16px 20px;
    border-radius: var(--r-lg);
    background: var(--bg-2);
    border: 1px solid var(--border);
    text-align: center;
}
.footer-meta-note p {
    font-size: .85rem;
    color: var(--tx-3);
    line-height: 1.6;
}
.footer-meta-note p em {
    color: var(--tx-2);
    font-style: italic;
}

/* ═══════════════════════════ FOOTER ═══════════════════════════ */
.footer {
    padding: 56px 0 28px;
    border-top: 1px solid var(--border);
    margin-top: 32px;
}
.footer-inner {
    display: grid;
    grid-template-columns: 1.6fr 1fr 1fr;
    gap: 36px;
    padding-bottom: 40px;
}
.footer-brand-row {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
}
.footer-logo-wrap {
    width: 26px;
    height: 26px;
    border-radius: 8px;
    background: var(--grad);
    display: flex;
    align-items: center;
    justify-content: center;
}
.footer-logo-wrap img {
    width: 15px;
    height: 15px;
    filter: brightness(0) invert(1);
}
.footer-brand-name {
    font-family: var(--font-display);
    font-weight: 600;
    font-size: .95rem;
    color: var(--tx);
}
.footer-tagline {
    font-size: .83rem;
    color: var(--tx-3);
    max-width: 280px;
    line-height: 1.6;
    margin-bottom: 16px;
}
.footer-copy {
    font-size: .76rem;
    color: var(--tx-4);
    margin-bottom: 3px;
}
.footer-badges {
    display: flex;
    gap: 6px;
    flex-wrap: wrap;
    margin-top: 14px;
}
.footer-badge {
    font-size: .68rem;
    padding: 4px 10px;
    border-radius: var(--r-pill);
    border: 1px solid var(--border-2);
    color: var(--tx-3);
}
.badge-purple {
    border-color: rgba(124, 92, 255, .3);
    color: var(--violet-bright);
}
.badge-amber {
    border-color: rgba(255, 180, 84, .3);
    color: var(--amber);
}
.badge-green {
    border-color: rgba(74, 222, 128, .3);
    color: var(--success);
}
.footer-col-label {
    font-size: .72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .07em;
    color: var(--tx-4);
    margin-bottom: 14px;
}
.footer-links {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.footer-link {
    font-size: .83rem;
    color: var(--tx-3);
    transition: var(--ease);
}
.footer-link:hover {
    color: var(--tx);
}
.footer-bottom {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding-top: 22px;
    border-top: 1px solid var(--border);
    font-size: .76rem;
    color: var(--tx-4);
    flex-wrap: wrap;
}
.back-top-btn {
    background: none;
    border: 1px solid var(--border-2);
    border-radius: var(--r-md);
    padding: 6px 14px;
    font-size: .76rem;
    color: var(--tx-3);
    cursor: pointer;
    transition: var(--ease);
}
.back-top-btn:hover {
    color: var(--tx);
    border-color: var(--border-violet);
}

/* ═══════════════════════════ MODAL ═══════════════════════════ */
.modal-overlay {
    position: fixed;
    inset: 0;
    z-index: 2000;
    background: rgba(4, 4, 6, .7);
    backdrop-filter: blur(6px);
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
    opacity: 1;
    transition: opacity .25s ease;
}
.modal-overlay.hidden {
    display: none;
}
.modal-box {
    position: relative;
    width: 100%;
    max-width: 420px;
    background: var(--bg-2);
    border: 1px solid var(--border-2);
    border-radius: var(--r-xl);
    padding: 30px;
    box-shadow: var(--shadow-card);
    animation: modalIn .3s cubic-bezier(.16, 1, .3, 1);
    max-height: 88vh;
    overflow-y: auto;
}
@keyframes modalIn {
    from {
        opacity: 0;
        transform: scale(.96) translateY(8px);
    }
    to {
        opacity: 1;
        transform: scale(1) translateY(0);
    }
}
.modal-close {
    position: absolute;
    top: 16px;
    right: 16px;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: rgba(255, 255, 255, .05);
    border: 1px solid var(--border-2);
    color: var(--tx-3);
    cursor: pointer;
}
.modal-close:hover {
    color: var(--tx);
}
.modal-kicker {
    font-size: .72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .06em;
    color: var(--violet-bright);
    margin-bottom: 8px;
}
.modal-title {
    font-family: var(--font-display);
    font-size: 1.3rem;
    font-weight: 600;
    color: var(--tx);
    margin-bottom: 8px;
    letter-spacing: -.01em;
}
.modal-body-text {
    font-size: .85rem;
    color: var(--tx-3);
    line-height: 1.6;
    margin-bottom: 20px;
}
.auth-seg {
    display: flex;
    background: var(--bg);
    border: 1px solid var(--border-2);
    border-radius: var(--r-md);
    padding: 3px;
}
.auth-seg-btn {
    flex: 1;
    padding: 8px;
    border-radius: var(--r-sm);
    background: none;
    border: none;
    font-size: .82rem;
    font-weight: 600;
    color: var(--tx-3);
    cursor: pointer;
    transition: var(--ease);
}
.auth-seg-btn.active {
    background: var(--bg-2);
    color: var(--tx);
    box-shadow: var(--shadow-card);
}
.checkout-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
}
.field {
    margin-bottom: 16px;
}
.field label {
    display: block;
    font-size: .76rem;
    font-weight: 600;
    color: var(--tx-2);
    margin-bottom: 6px;
}
input[type="email"],
input[type="password"],
input[type="text"] {
    width: 100%;
    background: var(--bg);
    border: 1px solid var(--border-2);
    border-radius: var(--r-md);
    padding: 11px 14px;
    font-size: .87rem;
    color: var(--tx);
    transition: var(--ease);
}
input:focus {
    border-color: var(--violet-bright);
    box-shadow: 0 0 0 3px rgba(124, 92, 255, .15);
}
.err {
    font-size: .78rem;
    color: var(--danger);
}
.hidden {
    display: none !important;
}

/* ═══════════════════════════ RESPONSIVE ═══════════════════════════ */
@media (max-width:1024px) {
    .section {
        padding: 48px 0;
    }
    .disclaimer-grid {
        grid-template-columns: 1fr;
    }
    .footer-inner {
        grid-template-columns: 1fr 1fr;
        gap: 28px;
    }
    .footer-inner>div:first-child {
        grid-column: 1 / -1;
    }
}
@media (max-width:820px) {
    body {
        padding-top: calc(var(--nav-h) + 14px);
    }
    .main-wrap {
        padding: 0 18px 40px;
    }
    .section {
        padding: 36px 0;
    }
    .disclaimer-card {
        padding: 18px 20px;
    }
}
@media (max-width:480px) {
    .section-title {
        font-size: 1.6rem;
    }
    .section-sub {
        font-size: .85rem;
    }
    .disclaimer-card .dc-title {
        font-size: .95rem;
    }
    .disclaimer-card .dc-body {
        font-size: .8rem;
    }
    .footer-bottom {
        flex-direction: column;
        align-items: flex-start;
    }
    .modal-box {
        padding: 20px 16px;
    }
    .checkout-row {
        grid-template-columns: 1fr;
    }
}

scripts.content:
'use strict';

const BASE_URL = "https://mohammadtalhaa-free-voice-labs-backend.hf.space";
const SESSION_KEY = "fvl_session";

const getSession = () => { try { const r = sessionStorage.getItem(SESSION_KEY); return r ? JSON.parse(r) : null; } catch {
        return null; } };
const setSession = d => { try { sessionStorage.setItem(SESSION_KEY, JSON.stringify(d)); } catch {} };
const clearSession = () => { try { sessionStorage.removeItem(SESSION_KEY); } catch {} };
const isLoggedIn = () => { const s = getSession(); return !!(s?.email && s?.token); };

async function apiFetch(path, opts = {}) {
    const s = getSession();
    const headers = { "Content-Type": "application/json", ...(s?.token ? { Authorization: `Bearer ${s.token}` } : {}),
        ...(opts.headers || {}) };
    const res = await fetch(`${BASE_URL}${path}`, { ...opts, headers: opts.formData ? (opts.headers || {}) :
            headers });
    if (!res.ok) { let m = `HTTP ${res.status}`; try { const e = await res.json();
            m = e.detail || e.message || m; } catch {} throw new Error(m); }
    if (opts.binary) return res;
    return res.json();
}

function renderNavAuth() {
    const container = document.getElementById("island-right");
    if (!container) return;
    const s = getSession();
    if (s?.email) {
        const initials = s.email.substring(0, 2).toUpperCase();
        container.innerHTML =
            `<div class="island-profile" onclick="openSignInModal()"><div class="island-avatar">${initials}</div><span class="island-profile-email">${s.email}</span><span class="chevron">▾</span></div><button class="island-btn island-btn-ghost island-btn-sm" onclick="handleLogout()">Sign Out</button>`;
        checkAndShowAdminLink();
    } else {
        container.innerHTML =
            `<button class="island-btn island-btn-secondary island-btn-sm" onclick="openSignInModal()">Sign In</button><button class="island-btn island-btn-primary island-btn-sm" onclick="openCheckout('monthly')">Get Started</button>`;
        const adminLink = document.getElementById("nav-admin-link");
        if (adminLink) adminLink.style.display = "none";
    }
}

function checkAndShowAdminLink() {
    const adminLink = document.getElementById("nav-admin-link");
    const s = getSession();
    if (adminLink && s && s.email === "talha@vfl.ai") { adminLink.style.display = "flex";
        adminLink.onclick = (e) => { e.preventDefault();
            window.location.href = "/admin"; }; } else if (adminLink) { adminLink.style.display = "none"; }
}

function handleLogout() { clearSession();
    renderNavAuth();
    renderMobileNav();
    const adminLink = document.getElementById("nav-admin-link"); if (adminLink) adminLink.style.display = "none";
    closeCheckout(); }

function renderMobileNav() {
    const overlay = document.getElementById("island-mobile-overlay");
    if (!overlay) return;
    const s = getSession();
    const isAdmin = s && s.email === "talha@vfl.ai";
    overlay.innerHTML =
        `<div class="mob-section">Products</div><a href="/#studio" class="mob-link"><span class="mob-icon">🧠</span> Neural TTS</a><a href="/#studio" class="mob-link"><span class="mob-icon">🎭</span> Blends</a><a href="/#studio" class="mob-link"><span class="mob-icon">📻</span> Podcast Mode</a><a href="/#studio" class="mob-link"><span class="mob-icon">🔬</span> Voice Cloning<span class="mob-badge">Beta</span></a><div class="mob-divider"></div><a href="/#pricing" class="mob-link"><span class="mob-icon">💎</span> Pricing</a><a href="/#platform" class="mob-link"><span class="mob-icon">⚙️</span> Platform</a><a href="/#testimonials" class="mob-link"><span class="mob-icon">⭐</span> Testimonials</a><div class="mob-divider"></div><div class="mob-section">About</div><a href="/about" class="mob-link"><span class="mob-icon">📖</span> About Us</a><a href="/contact" class="mob-link"><span class="mob-icon">📧</span> Contact</a><a href="/feature-requests" class="mob-link"><span class="mob-icon">💡</span> Feature Requests</a><a href="/privacy" class="mob-link"><span class="mob-icon">🔒</span> Privacy</a><a href="/terms" class="mob-link"><span class="mob-icon">📜</span> Terms</a><a href="/disclaimers" class="mob-link"><span class="mob-icon">⚠️</span> Disclaimers</a><a href="/sitemap" class="mob-link"><span class="mob-icon">🗺️</span> Sitemap</a>${isAdmin ? `<a href="#" class="mob-link" onclick="event.preventDefault(); window.location.href='/admin'; closeMobileNav();"><span class="mob-icon">👑</span> Admin Dashboard</a>` : ""
    }<div class="mob-divider"></div>${s?.email ? `
                <div style="padding:8px 16px;font-size:.78rem;color:var(--tx-3);">Signed in as <strong style="color:var(--tx-2);">${s.email}</strong></div>
                <button class="mob-link" onclick="handleLogout();closeMobileNav();" style="color:var(--danger);"><span class="mob-icon">🚪</span> Sign Out</button>
            ` : `
                <div class="mob-auth-row">
                    <button class="mob-link" onclick="openSignInModal();closeMobileNav();" style="color:var(--violet-bright);"><span class="mob-icon">🔑</span> Sign In</button>
                    <button class="mob-link" onclick="openCheckout('monthly');closeMobileNav();" style="color:var(--tx-2);"><span class="mob-icon">🚀</span> Get Started</button>
                </div>
            `}`;
}

function closeMobileNav() { const o = document.getElementById("island-mobile-overlay"),
        h = document.getElementById("island-hamburger"),
        c = document.getElementById("island-overlay-close"); if (o) o.classList.remove("open"); if (h) { h.classList
            .remove("open");
        h.setAttribute("aria-expanded", "false"); } if (c) c.classList.remove("visible");
    document.body.style.overflow = ""; }

function toggleMobileNav() { const o = document.getElementById("island-mobile-overlay"),
        h = document.getElementById("island-hamburger"),
        c = document.getElementById("island-overlay-close"); if (!o || !h) return; const open = o.classList
        .toggle("open");
    h.classList.toggle("open", open);
    h.setAttribute("aria-expanded", open); if (c) c.classList.toggle("visible", open);
    document.body.style.overflow = open ? "hidden" : ""; }

function openSignInModal() {
    const overlay = document.getElementById("modal-overlay");
    if (overlay) { overlay.classList.remove("hidden");
        overlay.onclick = e => { if (e.target === overlay) closeCheckout(); }; }
    document.addEventListener("keydown", escClose);
    renderSignInModal();
}

function renderSignInModal() {
    const body = document.getElementById("modal-body");
    if (!body) return;
    body.innerHTML =
        `<button class="modal-close" onclick="closeCheckout()" aria-label="Close">✕</button><div class="modal-kicker">Welcome Back</div><div class="modal-title">Sign in to your account</div><div class="modal-body-text">Access your saved voices, history, and premium features.</div><div class="auth-seg" style="margin-bottom:14px;"><button class="auth-seg-btn ${authTab === 'signin' ? 'active' : ''}" onclick="setModalAuthTab('signin')">Sign In</button><button class="auth-seg-btn ${authTab === 'signup' ? 'active' : ''}" onclick="setModalAuthTab('signup')">Sign Up</button></div><div id="modal-auth-form"></div><button class="btn btn-ghost btn-full btn-sm" style="margin-top:8px;" onclick="closeCheckout()">Cancel</button>`;
    renderModalAuthForm();
}

function openCheckout(plan) {
    checkoutPlan = plan;
    const overlay = document.getElementById("modal-overlay");
    if (overlay) { overlay.classList.remove("hidden");
        overlay.onclick = e => { if (e.target === overlay) closeCheckout(); }; }
    document.addEventListener("keydown", escClose);
    renderCheckoutModal();
}

function closeCheckout() { const overlay = document.getElementById("modal-overlay"); if (overlay) overlay.classList
        .add("hidden");
    document.removeEventListener("keydown", escClose);
    checkoutPlan = null; }

function escClose(e) { if (e.key === "Escape") closeCheckout(); }

let checkoutPlan = null,
    authTab = "signin";

function renderCheckoutModal() {
    const body = document.getElementById("modal-body");
    if (!body) return;
    const s = getSession();
    if (!s?.email) {
        body.innerHTML =
            `<button class="modal-close" onclick="closeCheckout()" aria-label="Close">✕</button><div class="modal-kicker">Secure Checkout · ${checkoutPlan} Plan</div><div class="modal-title">Sign in to Continue</div><div class="modal-body-text">Create an account or sign in to complete your purchase.</div><div class="auth-seg" style="margin-bottom:14px;"><button class="auth-seg-btn ${authTab === 'signin' ? 'active' : ''}" onclick="setModalAuthTab('signin')">Sign In</button><button class="auth-seg-btn ${authTab === 'signup' ? 'active' : ''}" onclick="setModalAuthTab('signup')">Sign Up</button></div><div id="modal-auth-form"></div><button class="btn btn-ghost btn-full btn-sm" style="margin-top:8px;" onclick="closeCheckout()">Cancel</button>`;
        renderModalAuthForm();
    } else {
        body.innerHTML =
            `<button class="modal-close" onclick="closeCheckout()" aria-label="Close">✕</button><div class="modal-kicker">Secure Checkout · ${checkoutPlan} Plan</div><div class="modal-title">Unlock ${checkoutPlan.charAt(0).toUpperCase() + checkoutPlan.slice(1)}</div><div class="modal-body-text">Complete your payment to activate your plan instantly.</div><div class="field"><label for="ck-name">Name on Card</label><input id="ck-name" type="text" placeholder="John Smith"></div><div class="field"><label for="ck-email">Billing Email</label><input id="ck-email" type="email" placeholder="you@example.com" value="${s.email}"></div><div class="field"><label for="ck-card">Card Number</label><input id="ck-card" type="text" placeholder="4242 4242 4242 4242" maxlength="19"></div><div class="checkout-row"><div class="field"><label for="ck-expiry">Expiry</label><input id="ck-expiry" type="text" placeholder="MM/YY" maxlength="5"></div><div class="field"><label for="ck-cvv">CVV</label><input id="ck-cvv" type="text" placeholder="123" maxlength="4"></div></div><div id="ck-err" class="err" style="display:none; margin-bottom:8px;"></div><button class="btn btn-primary btn-full" onclick="handleCheckout()">Pay &amp; Activate →</button>`;
    }
}

function setModalAuthTab(tab) { authTab = tab;
    renderCheckoutModal(); }

function renderModalAuthForm() {
    const el = document.getElementById("modal-auth-form");
    if (!el) return;
    if (authTab === "signin") {
        el.innerHTML =
            `<div class="field"><label for="m-login-email">Email</label><input type="email" id="m-login-email" autocomplete="email"></div><div class="field"><label for="m-login-pw">Password</label><input type="password" id="m-login-pw"></div><div id="m-login-err" class="err" style="display:none; margin-bottom:8px;"></div><button class="btn btn-primary btn-full" onclick="handleModalLogin()">Sign In</button>`;
    } else {
        el.innerHTML =
            `<div class="field"><label for="m-signup-email">Email</label><input type="email" id="m-signup-email" autocomplete="email"></div><div class="field"><label for="m-signup-pw">Password</label><input type="password" id="m-signup-pw"></div><div class="field"><label for="m-signup-pw2">Confirm</label><input type="password" id="m-signup-pw2"></div><div id="m-signup-err" class="err" style="display:none; margin-bottom:8px;"></div><button class="btn btn-primary btn-full" onclick="handleModalSignup()">Create Account</button>`;
    }
}

async function handleModalLogin() {
    const email = document.getElementById("m-login-email")?.value.trim().toLowerCase() || "";
    const pw = document.getElementById("m-login-pw")?.value || "";
    const errEl = document.getElementById("m-login-err");
    if (errEl) errEl.style.display = "none";
    try {
        const data = await apiFetch("/api/auth/login", { method: "POST", body: JSON.stringify({ email,
                password: pw }) });
        setSession({ email: data.email, token: data.token, plan: data.plan });
        renderNavAuth();
        renderMobileNav();
        closeCheckout();
        if (checkoutPlan) renderCheckoutModal();
    } catch (e) { if (errEl) { errEl.textContent = e.message;
            errEl.style.display = ""; } }
}

async function handleModalSignup() {
    const email = document.getElementById("m-signup-email")?.value.trim().toLowerCase() || "";
    const pw = document.getElementById("m-signup-pw")?.value || "";
    const pw2 = document.getElementById("m-signup-pw2")?.value || "";
    const errEl = document.getElementById("m-signup-err");
    if (errEl) errEl.style.display = "none";
    if (pw !== pw2) { if (errEl) { errEl.textContent = "Passwords don't match.";
            errEl.style.display = ""; } return; }
    try {
        const data = await apiFetch("/api/auth/signup", { method: "POST", body: JSON.stringify({ email,
                password: pw }) });
        setSession({ email: data.email, token: data.token, plan: data.plan });
        renderNavAuth();
        renderMobileNav();
        closeCheckout();
        if (checkoutPlan) renderCheckoutModal();
    } catch (e) { if (errEl) { errEl.textContent = e.message;
            errEl.style.display = ""; } }
}

async function handleCheckout() {
    const s = getSession();
    const name = document.getElementById("ck-name")?.value.trim() || "";
    const email = document.getElementById("ck-email")?.value.trim() || "";
    const card = document.getElementById("ck-card")?.value.trim() || "";
    const errEl = document.getElementById("ck-err");
    if (errEl) errEl.style.display = "none";
    if (!name || !email || !card) return;
    try {
        const r = await apiFetch("/api/checkout", { method: "POST", body: JSON.stringify({ email: s.email,
                plan_name: checkoutPlan, billing_name: name, billing_email: email, card_number: card }) });
        const body = document.getElementById("modal-body");
        if (body) {
            body.innerHTML =
                `<div style="text-align:center;padding:24px 0;"><div style="font-size:3rem;margin-bottom:18px;animation:bounceIn .6s ease both;">✓</div><div class="modal-kicker">Payment Successful</div><div class="modal-title">${checkoutPlan.charAt(0).toUpperCase() + checkoutPlan.slice(1)} Activated!</div><div class="modal-body-text">Your plan has been activated immediately. Get started!</div>${r.receipt ? `<div style="background:rgba(124,92,255,.06);border:1px solid var(--border);border-radius:var(--r-md);padding:14px;margin:16px 0;text-align:left;"><div style="font-size:.75rem;color:var(--tx-3);line-height:1.9;"><div>Reference: <strong style="color:var(--violet-bright);">${r.receipt.reference}</strong></div><div>Amount: <strong style="color:var(--tx);">${r.receipt.amount}</strong></div><div>Card: **** ${r.receipt.card_last4}</div></div></div>` : ""
                }<button class="btn btn-primary btn-full" onclick="closeCheckout()">Get Started</button></div>`;
        }
        setSession({ ...s, plan: checkoutPlan });
        renderNavAuth();
        renderMobileNav();
    } catch (e) { if (errEl) { errEl.textContent = e.message;
            errEl.style.display = ""; } }
}

function setupReveal() {
    const io = new IntersectionObserver(entries => { entries.forEach(e => { if (e.isIntersecting) { e.target
                .classList.add("in");
                io.unobserve(e.target); } }); }, { threshold: 0.06, rootMargin: "0px 0px -40px 0px" });
    document.querySelectorAll(".reveal").forEach(el => io.observe(el));
}

function setupEvents() {
    document.getElementById("island-hamburger")?.addEventListener("click", toggleMobileNav);
    document.getElementById("island-overlay-close")?.addEventListener("click", closeMobileNav);
    document.getElementById("island-mobile-overlay")?.addEventListener("click", (e) => { if (e.target === e
            .currentTarget) closeMobileNav(); });
    document.addEventListener("input", e => {
        if (e.target.id === "ck-card") { let v = e.target.value.replace(/\D/g, "").slice(0, 16);
            e.target.value = v.replace(/(.{4})/g, "$1 ").trim(); }
        if (e.target.id === "ck-expiry") { let v = e.target.value.replace(/\D/g, "").slice(0, 4); if (v
                .length >= 3) v = v.slice(0, 2) + "/" + v.slice(2);
            e.target.value = v; }
    });
}

function boot() {
    const yr = document.getElementById("footer-year");
    if (yr) yr.textContent = `© ${new Date().getFullYear()} Free Voice Labs. All rights reserved.`;
    renderNavAuth();
    renderMobileNav();
    setupReveal();
    setupEvents();
    checkAndShowAdminLink();
}

